export interface CadTemplateAsset {
  ref: string;
  kind: string;
  label: string;
  x: number;
  y: number;
  w: number;
  h: number;
  rotation?: number;
  layer: CadLayerId;
  tags: string[];
}

export interface CadTemplateAnnotation {
  ref: string;
  type: "text";
  text: string;
  x: number;
  y: number;
  layer: CadLayerId;
}

export interface CadTemplateConnector {
  fromRef: string;
  toRef: string;
  kind: "flow" | "material";
}

export interface CadLayoutTemplate {
  id: CadLayoutTemplateId;
  label: string;
  description: string;
  category: "factory" | "production" | "warehouse" | "shipping" | "architecture" | "civil" | "structure" | "mep";
  baseWidth: number;
  baseHeight: number;
  assets: CadTemplateAsset[];
  annotations: CadTemplateAnnotation[];
  connectors: CadTemplateConnector[];
}

export interface CadTemplateInstantiation {
  template: CadLayoutTemplate;
  scale: number;
  assets: CadTemplateAsset[];
  annotations: CadTemplateAnnotation[];
  connectors: CadTemplateConnector[];
  warnings: string[];
}

const asset = (
  ref: string,
  kind: string,
  label: string,
  x: number,
  y: number,
  w: number,
  h: number,
  layer: CadLayerId,
  tags: string[],
  rotation = 0,
): CadTemplateAsset => ({ ref, kind, label, x, y, w, h, layer, tags, rotation });

const note = (
  ref: string,
  text: string,
  x: number,
  y: number,
  layer: CadLayerId,
): CadTemplateAnnotation => ({ ref, type: "text", text, x, y, layer });

